static void VerticalRing(SkyRuinMesh target,Vector3 c,float r,float width,float depth,int segments=48,float start=0,float end=6.283185f){var temp=new SkyRuinMesh();for(int i=0;i<segments;i++)temp.Wedge(Vector3.zero,r-width/2,r+width/2,Mathf.Lerp(start,end,i/(float)segments),Mathf.Lerp(start,end,(i+1)/(float)segments),depth,2);var q=Quaternion.Euler(90,0,0);int offset=target.v.Count;foreach(var p in temp.v)target.v.Add(c+q*p);target.uv.AddRange(temp.uv);target.tri.AddRange(temp.tri.Select(t=>t+offset));}
