static void FoundationUpgrade(Transform pass){var g=Group("28_Layered_Floating_Foundations");foreach(var tuple in V3Places()){Vector3 c=tuple.Item1;float r=tuple.Item2;var layers=new SkyRuinMesh();for(int i=0;i<16;i++){float a=i*6.283185f/16,b=(i+1)*6.283185f/16;layers.Wedge(c-Vector3.up*1.1f,r-.55f,r+.1f,a+.006f,b-.006f,.42f,3);layers.Wedge(c-Vector3.up*1.6f,r-1.1f,r-.3f,a+.012f,b-.012f,.42f,3);}Mesh(layers,tuple.Item3+"_Layered_Foundation_Masonry",dark,g);for(int i=0;i<6;i++){float a=i*6.283185f/6;var p=c+P(Mathf.Cos(a)*(r-.5f),-3.4f,Mathf.Sin(a)*(r-.5f));var rock=Prop("SM_Rock_Medium_01",g,p,R(2.3f,3.5f),R(0,360));foreach(var rr in rock.GetComponentsInChildren<MeshRenderer>())rr.sharedMaterials=rr.sharedMaterials.Select(m=>cliff).ToArray();}}
