static void CrystalMesh(SkyRuinMesh a,SkyRuinMesh b,Vector3 c,float radius,float height,int seed){var rand=new System.Random(seed);int n=7;var lower=new Vector3[n];var upper=new Vector3[n];Vector3 bottom=c-Vector3.up*height*.45f,tip=c+P(radius*.13f,height*.58f,-radius*.12f);for(int i=0;i<n;i++){float angle=i*6.283185f/n;float r=radius*(.88f+(float)rand.NextDouble()*.2f);lower[i]=c+P(Mathf.Cos(angle)*r,-height*.22f,Mathf.Sin(angle)*r);upper[i]=c+P(Mathf.Cos(angle)*r*.8f,height*.22f,Mathf.Sin(angle)*r*.8f);}for(int i=0;i<n;i++){int j=(i+1)%n;var m=i%3==0?b:a;m.Face(bottom,lower[i],lower[j]);m.Face(lower[i],upper[i],upper[j],lower[j]);m.Face(upper[i],tip,upper[j]);}}
